public RefreshFrequency xds()
{
    METInventSitePolicyTmp         metInventSitePolicyTmp;
    METUserSecurityGroupList       metUserSecurityGroupList;
    METUserSecuritySiteList        metUserSecuritySiteList;
    InventSite                     inventSite;        

    Unchecked(Uncheck::XDS)
    {
        insert_recordset metInventSitePolicyTmp(SiteId)
            select SiteId from inventSite
                join metUserSecuritySiteList
            where metUserSecuritySiteList.SiteId == inventSite.RecId
                join metUserSecurityGroupList
            where metUserSecurityGroupList.UserSecurityGroupId == metUserSecuritySiteList.UserSecurityGroupId
            && metUserSecurityGroupList.UserId == curUserId();

        // Insert blank SiteId for records without site assignment
        metInventSitePolicyTmp.clear();
        metInventSitePolicyTmp.SiteId = '';
        metInventSitePolicyTmp.insert();
    }

    return RefreshFrequency::PerSession;
}
